def count_valid_dates_in_list(date_list):
    def is_valid(s):
        if not isinstance(s, str) or len(s) != 10 or s[4] != "-" or s[7] != "-":
            return False
        yp, mp, dp = s[0:4], s[5:7], s[8:10]
        if not (yp.isdigit() and mp.isdigit() and dp.isdigit()):
            return False
        y, m, d = int(yp), int(mp), int(dp)
        if m < 1 or m > 12:
            return False
        def is_leap(yr):
            return yr % 4 == 0 and (yr % 100 != 0 or yr % 400 == 0)
        dim = [31, 29 if is_leap(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]
        return 1 <= d <= dim
    return sum(1 for s in date_list if is_valid(s))

def shift_time_by_hours(hh, mm, offset_hours):
    total = hh * 60 + mm + offset_hours * 60
    day_delta = total // 1440
    rem = total % 1440
    return (rem // 60, rem % 60, day_delta)

def shift_time_by_minutes(hh, mm, offset_minutes):
    total = hh * 60 + mm + offset_minutes
    day_delta = total // 1440
    rem = total % 1440
    return (rem // 60, rem % 60, day_delta)

def convert_between_timezones(time_str, from_offset_min, to_offset_min):
    hh, mm = map(int, time_str.split(":"))
    total = hh * 60 + mm - from_offset_min + to_offset_min
    day_delta = total // 1440
    rem = total % 1440
    return (f"{rem // 60:02d}:{rem % 60:02d}", day_delta)

def utc_to_local(hh, mm, utc_offset_minutes):
    total = hh * 60 + mm + utc_offset_minutes
    day_delta = total // 1440
    rem = total % 1440
    return (rem // 60, rem % 60, day_delta)

def local_to_utc(hh, mm, utc_offset_minutes):
    total = hh * 60 + mm - utc_offset_minutes
    day_delta = total // 1440
    rem = total % 1440
    return (rem // 60, rem % 60, day_delta)

def time_after_flight(depart_hhmm, flight_minutes, tz_offset_minutes):
    hh, mm = map(int, depart_hhmm.split(":"))
    total = hh * 60 + mm + flight_minutes + tz_offset_minutes
    day_delta = total // 1440
    rem = total % 1440
    return (f"{rem // 60:02d}:{rem % 60:02d}", day_delta)

def normalize_time_overflow(hh, mm):
    total = hh * 60 + mm
    day_delta = total // 1440
    rem = total % 1440
    return (rem // 60, rem % 60, day_delta)

def combine_time_offsets(hh, mm, offset1_minutes, offset2_minutes):
