def weekend_count_given_start_weekday(start_weekday, num_days):
    count = 0
    for i in range(num_days):
        if (start_weekday + i) % 7 in (5, 6):
            count += 1
    return count

def count_full_weekends_in_range(start_day_num, end_day_num):
    count = 0
    for d in range(start_day_num, end_day_num):
        if d % 7 == 5 and d + 1 <= end_day_num and (d + 1) % 7 == 6:
            count += 1
    return count
